def solution(nums):
    unique_types = len(set(nums))
    return min(unique_types, len(nums) // 2)

def solution(arr):
    if len(arr) == 1:
        return [-1]
    arr.remove(min(arr))
    return arr

def solution(k, score):
    honor = []
    result = []

    for s in score:
        honor.append(s)
        if len(honor) > k:
            honor.remove(min(honor))
        result.append(min(honor) if len(honor) == k else honor[0])

    return result

def solution(food):
    answer = ''
    for i in range(1, len(food)):
        answer += str(i) * (food[i] // 2)
    return answer + '0' + answer[::-1]

def solution(s):
    def is_valid(string):
        stack = []
        pairs = {')': '(', ']': '[', '}': '{'}
        for char in string:
            if char in pairs.values():
                stack.append(char)
            elif char in pairs.keys():
                if not stack or stack[-1] != pairs[char]:
                    return False
                stack.pop()
        return not stack

    count = 0
    for i in range(len(s)):
        if is_valid(s[i:] + s[:i]):
            count += 1
    return count

def solution(wallpaper):
    min_x = len(wallpaper)
    min_y = len(wallpaper[0])
    max_x = 0
    max_y = 0

    for i in range(len(wallpaper)):
        for j in range(len(wallpaper[0])):
            if wallpaper[i][j] == '#':
                min_x = min(min_x, i)
                min_y = min(min_y, j)
                max_x = max(max_x, i + 1)
                max_y = max(max_y, j + 1)

    return [min_x, min_y, max_x, max_y]

def solution(storey):
    count = 0
    while storey > 0:
        remainder = storey % 10
        if remainder > 5:
            count += 10 - remainder
            storey += 10
        else:
            count += remainder
        storey //= 10
    return count

def solution(r1, r2):
    count = 0
    for x in range(-r2, r2 + 1):
        y_limit1 = int((r1**2 - x**2)**0.5) if r1**2 - x**2 >= 0 else 0
        y_limit2 = int((r2**2 - x**2)**0.5)
        count += y_limit2 - y_limit1
    return count * 2 + (r1 == 0) + (r2 == 0)

def solution(land):
    for i in range(1, len(land)):
        for j in range(4):
            land[i][j] += max(land[i-1][(j+1)%4], land[i-1][(j+2)%4], land[i-1][(j+3)%4])
    return max(land[-1])

def solution(arr, divisor):
    result = [x for x in arr if x % divisor == 0]
    return sorted(result) if result else [-1]

def solution(nums):
    from itertools import combinations

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    count = 0
    for combo in combinations(nums, 3):
        if is_prime(sum(combo)):
            count += 1

    return count

def solution(data, ext, val_ext, sort_by):
    ext_index = {"code": 0, "date": 1, "maximum": 2, "remain": 3}
    sort_index = ext_index[sort_by]
    filtered_data = [item for item in data if item[ext_index[ext]] < val_ext]
    return sorted(filtered_data, key=lambda x: x[sort_index])

def solution(survey, choices):
    score_map = {1: 3, 2: 2, 3: 1, 4: 0, 5: 1, 6: 2, 7: 3}
    personality_scores = {'R': 0, 'T': 0, 'C': 0, 'F': 0, 'J': 0, 'M': 0, 'A': 0, 'N': 0}

    for i in range(len(survey)):
        s = survey[i]
        choice = choices[i]
        score = score_map[choice]

        if choice < 4:
            personality_scores[s[0]] += score
        elif choice > 4:
            personality_scores[s[1]] += score

    result = ''
    for key in ['R', 'C', 'J', 'A']:
        if personality_scores[key] >= personality_scores[chr(ord(key) + 1)]:
            result += key
        else:
            result += chr(ord(key) + 1)

    return result
